package org.jsoup.parser;

import org.jsoup.helper.Validate;
import org.jsoup.internal.Normalizer;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.Mockito;
import org.mockito.junit.MockitoJUnitRunner;

import java.util.HashMap;
import java.util.Map;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

@RunWith(MockitoJUnitRunner.class)
public class TagTest {

    @Mock
    private ParseSettings settings;

    @Test
    public void getName_ValidTagName_ReturnsTagName() {
        String tagName = "div";
        Tag tag = new Tag(tagName);
        assertEquals(tagName, tag.getName());
    }

    @Test
    public void normalName_ValidTagName_ReturnsNormalizedTagName() {
        String tagName = "<p>";
        Tag tag = new Tag(tagName);
        assertEquals("p", tag.normalName());
    }

    @Test
    public void valueOf_ValidTagName_returnsTag() {
        String tagName = "img";
        Tag expectedTag = new Tag(tagName);
        Tag actualTag = Tag.valueOf(tagName, settings);
        Mockito.verify(expectedTag).getName();
    }

    @Test
    public void valueOf_UnknownTagName_throwsException() {
        String tagName = "<unknown>";
        assertThrows(NullPointerException.class, () -> Tag.valueOf(tagName));
    }

    @Test
    public void isBlock_ValidTagName_returnsTrue() {
        String tagName = "div";
        Tag tag = new Tag(tagName);
        assertTrue(tag.isBlock());
    }

    @Test
    public void formatAsBlock_ValidTagName_returnsFalse() {
        String tagName = "span";
        Tag tag = new Tag(tagName);
        assertFalse(tag.formatAsBlock());
    }

    @Test
    public void isInline_ValidTagName_returnsTrue() {
        String tagName = "span";
        Tag tag = new Tag(tagName);
        assertTrue(tag.isInline());
    }

    @Test
    public void isEmpty_ValidTagName_ReturnsFalse() {
        String tagName = "img";
        Tag tag = new Tag(tagName);
        assertFalse(tag.isEmpty());
    }

    @Test
    public void isSelfClosing_ValidTagName_ReturnsTrue() {
        String tagName = "img";
        Tag tag = new Tag(tagName);
        assertTrue(tag.isSelfClosing());
    }

    @Test
    public void isKnownTag_ValidTagName_returnsTrue() {
        String tagName = "div";
        assertTrue(Tag.isKnownTag(tagName));
    }

    @Test
    public void preserveWhitespace_ValidTagName_ReturnsFalse() {
        String tagName = "img";
        Tag tag = new Tag(tagName);
        assertFalse(tag.preserveWhitespace());
    }

    @Test
    public void isFormListed_ValidTagName_returnsTrue() {
        String tagName = "form";
        Tag tag = new Tag(tagName);
        assertTrue(tag.isFormListed());
    }

    @Test
    public void isFormSubmittable_ValidTagName_ReturnsFalse() {
        String tagName = "span";
        Tag tag = new Tag(tagName);
        assertFalse(tag.isFormSubmittable());
    }

    @Test
    public void setSelfClosing_ValidTagName_setsTrue() {
        String tagName = "img";
        Tag expectedTag = new Tag(tagName);
        expectedTag.setSelfClosing();
        Tag actualTag = new Tag(tagName);
        assertEquals(expectedTag, actualTag.setSelfClosing());
    }
}
